=== FILE: axi4_lite_regs.v ===
`default_nettype none

// axi4_lite_regs
// Four 32-bit read/write registers behind an AXI4-Lite subordinate port.
// Implements microarchitecture.md:
//   * READY is a function of state only (no VALID->READY paths).
//   * Holding registers for a write address or write data that arrives alone.
//   * The write fires on the edge that completes the AW/W pair.
//   * One outstanding transaction per direction, 1-cycle response latency.
//   * Unmapped (misaligned) addresses answer SLVERR; reads return zero.
//   * aresetn is synchronous, active low.
module axi4_lite_regs #(
    parameter integer ADDR_WIDTH = 4,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                      aclk,
    input  wire                      aresetn,

    input  wire [ADDR_WIDTH-1:0]     s_axil_awaddr,
    input  wire                      s_axil_awvalid,
    output wire                      s_axil_awready,

    input  wire [DATA_WIDTH-1:0]     s_axil_wdata,
    input  wire [DATA_WIDTH/8-1:0]   s_axil_wstrb,
    input  wire                      s_axil_wvalid,
    output wire                      s_axil_wready,

    output wire [1:0]                s_axil_bresp,
    output wire                      s_axil_bvalid,
    input  wire                      s_axil_bready,

    input  wire [ADDR_WIDTH-1:0]     s_axil_araddr,
    input  wire                      s_axil_arvalid,
    output wire                      s_axil_arready,

    output wire [DATA_WIDTH-1:0]     s_axil_rdata,
    output wire [1:0]                s_axil_rresp,
    output wire                      s_axil_rvalid,
    input  wire                      s_axil_rready
);

    localparam integer STRB_WIDTH  = DATA_WIDTH / 8;
    localparam [1:0]   RESP_OKAY   = 2'b00;
    localparam [1:0]   RESP_SLVERR = 2'b10;

    // ------------------------------------------------------------------
    // Helper functions
    // ------------------------------------------------------------------

    // Mapped when word aligned and inside the 16-byte window.
    function is_mapped;
        input [ADDR_WIDTH-1:0] a;
        begin
            is_mapped = (a[1:0] == 2'b00) && ((a >> 4) == {ADDR_WIDTH{1'b0}});
        end
    endfunction

    // Copy each byte of new_word whose strobe is set; keep the others.
    function [DATA_WIDTH-1:0] merge;
        input [DATA_WIDTH-1:0] old_word;
        input [DATA_WIDTH-1:0] new_word;
        input [STRB_WIDTH-1:0] strb;
        integer i;
        begin
            merge = old_word;
            for (i = 0; i < STRB_WIDTH; i = i + 1) begin
                if (strb[i]) begin
                    merge[8*i +: 8] = new_word[8*i +: 8];
                end
            end
        end
    endfunction

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------
    reg                   aw_held;
    reg                   w_held;
    reg [ADDR_WIDTH-1:0]  aw_addr_q;   // datapath, not reset
    reg [DATA_WIDTH-1:0]  w_data_q;    // datapath, not reset
    reg [STRB_WIDTH-1:0]  w_strb_q;    // datapath, not reset

    reg                   bvalid_q;
    reg [1:0]             bresp_q;

    reg                   rvalid_q;
    reg [1:0]             rresp_q;
    reg [DATA_WIDTH-1:0]  rdata_q;

    reg [DATA_WIDTH-1:0]  reg0;
    reg [DATA_WIDTH-1:0]  reg1;
    reg [DATA_WIDTH-1:0]  reg2;
    reg [DATA_WIDTH-1:0]  reg3;

    // ------------------------------------------------------------------
    // Handshakes (READY from state only)
    // ------------------------------------------------------------------
    assign s_axil_awready = !aw_held && !bvalid_q;
    assign s_axil_wready  = !w_held  && !bvalid_q;
    assign s_axil_arready = !rvalid_q;

    assign s_axil_bvalid  = bvalid_q;
    assign s_axil_bresp   = bresp_q;
    assign s_axil_rvalid  = rvalid_q;
    assign s_axil_rresp   = rresp_q;
    assign s_axil_rdata   = rdata_q;

    wire aw_hs = s_axil_awvalid && s_axil_awready;
    wire w_hs  = s_axil_wvalid  && s_axil_wready;
    wire ar_hs = s_axil_arvalid && s_axil_arready;
    wire b_hs  = bvalid_q && s_axil_bready;
    wire r_hs  = rvalid_q && s_axil_rready;

    // The write fires on the edge that completes the AW/W pair.
    wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
    wire [DATA_WIDTH-1:0] wr_data = w_held  ? w_data_q  : s_axil_wdata;
    wire [STRB_WIDTH-1:0] wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;

    wire wr_mapped = is_mapped(wr_addr);
    wire rd_mapped = is_mapped(s_axil_araddr);

    // ------------------------------------------------------------------
    // Holding registers (datapath, no reset)
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (aw_hs) begin
            aw_addr_q <= s_axil_awaddr;
        end
        if (w_hs) begin
            w_data_q <= s_axil_wdata;
            w_strb_q <= s_axil_wstrb;
        end
    end

    // ------------------------------------------------------------------
    // Write side: held flags, register file, B channel
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held  <= 1'b0;
            w_held   <= 1'b0;
            bvalid_q <= 1'b0;
            bresp_q  <= RESP_OKAY;
            reg0     <= {DATA_WIDTH{1'b0}};
            reg1     <= {DATA_WIDTH{1'b0}};
            reg2     <= {DATA_WIDTH{1'b0}};
            reg3     <= {DATA_WIDTH{1'b0}};
        end else if (do_write) begin
            aw_held  <= 1'b0;
            w_held   <= 1'b0;
            bvalid_q <= 1'b1;
            if (wr_mapped) begin
                bresp_q <= RESP_OKAY;
                case (wr_addr[3:2])
                    2'd0: reg0 <= merge(reg0, wr_data, wr_strb);
                    2'd1: reg1 <= merge(reg1, wr_data, wr_strb);
                    2'd2: reg2 <= merge(reg2, wr_data, wr_strb);
                    2'd3: reg3 <= merge(reg3, wr_data, wr_strb);
                endcase
            end else begin
                bresp_q <= RESP_SLVERR;
            end
        end else begin
            if (aw_hs) begin
                aw_held <= 1'b1;
            end
            if (w_hs) begin
                w_held <= 1'b1;
            end
            if (b_hs) begin
                bvalid_q <= 1'b0;
            end
        end
    end

    // ------------------------------------------------------------------
    // Read side: R channel
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            rvalid_q <= 1'b0;
            rresp_q  <= RESP_OKAY;
            rdata_q  <= {DATA_WIDTH{1'b0}};
        end else if (ar_hs) begin
            rvalid_q <= 1'b1;
            if (rd_mapped) begin
                rresp_q <= RESP_OKAY;
                case (s_axil_araddr[3:2])
                    2'd0: rdata_q <= reg0;
                    2'd1: rdata_q <= reg1;
                    2'd2: rdata_q <= reg2;
                    2'd3: rdata_q <= reg3;
                endcase
            end else begin
                rresp_q <= RESP_SLVERR;
                rdata_q <= {DATA_WIDTH{1'b0}};
            end
        end else if (r_hs) begin
            rvalid_q <= 1'b0;
        end
    end

`ifdef FORMAL
    // ------------------------------------------------------------------
    // Design-intent properties (SymbiYosys, axi4_lite_regs.sby)
    // ------------------------------------------------------------------
    reg       f_past_valid;
    reg [1:0] f_aw_open;
    reg [1:0] f_w_open;
    reg [1:0] f_ar_open;

    initial f_past_valid = 1'b0;
    always @(posedge aclk) begin
        f_past_valid <= 1'b1;
    end

    // Manager assumptions: start in reset, VALID low in reset, and VALID
    // plus payload held until READY.
    always @(*) begin
        if (!f_past_valid) begin
            assume(!aresetn);
        end
        if (!aresetn) begin
            assume(!s_axil_awvalid && !s_axil_wvalid && !s_axil_arvalid);
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid && $past(aresetn) && aresetn) begin
            if ($past(s_axil_awvalid && !s_axil_awready)) begin
                assume(s_axil_awvalid && $stable(s_axil_awaddr));
            end
            if ($past(s_axil_wvalid && !s_axil_wready)) begin
                assume(s_axil_wvalid && $stable(s_axil_wdata) && $stable(s_axil_wstrb));
            end
            if ($past(s_axil_arvalid && !s_axil_arready)) begin
                assume(s_axil_arvalid && $stable(s_axil_araddr));
            end
        end
    end

    // Open-request counters: accepted requests minus accepted responses.
    always @(posedge aclk) begin
        if (!aresetn) begin
            f_aw_open <= 2'd0;
            f_w_open  <= 2'd0;
            f_ar_open <= 2'd0;
        end else begin
            f_aw_open <= f_aw_open + {1'b0, aw_hs} - {1'b0, b_hs};
            f_w_open  <= f_w_open  + {1'b0, w_hs}  - {1'b0, b_hs};
            f_ar_open <= f_ar_open + {1'b0, ar_hs} - {1'b0, r_hs};
        end
    end

    // State invariants.
    always @(*) begin
        if (f_past_valid) begin
            // At most one open request per direction; a response is pending
            // exactly when an accepted request awaits it.
            assert(f_aw_open == ((aw_held || bvalid_q) ? 2'd1 : 2'd0));
            assert(f_w_open  == ((w_held  || bvalid_q) ? 2'd1 : 2'd0));
            assert(f_ar_open == (rvalid_q ? 2'd1 : 2'd0));
            assert(!(aw_held && w_held));
            assert(!(bvalid_q && (aw_held || w_held)));
            assert((bresp_q == RESP_OKAY) || (bresp_q == RESP_SLVERR));
            assert((rresp_q == RESP_OKAY) || (rresp_q == RESP_SLVERR));
            if (rvalid_q && (rresp_q == RESP_SLVERR)) begin
                assert(rdata_q == {DATA_WIDTH{1'b0}});
            end
        end
        if (bvalid_q) begin
            assert(!s_axil_awready && !s_axil_wready);
        end
        if (rvalid_q) begin
            assert(!s_axil_arready);
        end
    end

    // Temporal properties.
    always @(posedge aclk) begin
        if (f_past_valid && !$past(aresetn)) begin
            assert(!bvalid_q);
            assert(!rvalid_q);
            assert(!aw_held && !w_held);
        end
        if (f_past_valid && $past(aresetn)) begin
            if ($past(bvalid_q && !s_axil_bready)) begin
                assert(bvalid_q && $stable(bresp_q));
            end
            if ($past(rvalid_q && !s_axil_rready)) begin
                assert(rvalid_q && $stable(rresp_q) && $stable(rdata_q));
            end
            if ($past(do_write)) begin
                assert(bvalid_q && (bresp_q == ($past(wr_mapped) ? RESP_OKAY : RESP_SLVERR)));
            end
            if (!$past(bvalid_q) && bvalid_q) begin
                assert($past(do_write));
            end
            if ($past(ar_hs)) begin
                assert(rvalid_q && (rresp_q == ($past(rd_mapped) ? RESP_OKAY : RESP_SLVERR)));
            end
            if (!$past(rvalid_q) && rvalid_q) begin
                assert($past(ar_hs));
            end
        end
    end

    // Covers: the proof is not vacuous.
    always @(posedge aclk) begin
        if (f_past_valid && $past(aresetn) && aresetn) begin
            cover($past(aw_held) && $past(w_hs));
            cover($past(w_held) && $past(aw_hs));
            cover($past(aw_hs && w_hs));
            cover(bvalid_q && (bresp_q == RESP_SLVERR) && s_axil_bready);
            cover(rvalid_q && (rresp_q == RESP_OKAY) && (rdata_q != {DATA_WIDTH{1'b0}}) && s_axil_rready);
            cover(rvalid_q && (rresp_q == RESP_SLVERR));
            cover($past(b_hs) && aw_hs);
            cover(bvalid_q && rvalid_q);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
