// Self-checking directed testbench for axi4_lite_regs.
// Inputs change after the falling edge; handshakes are sampled 1 ns before
// the rising edge, so there is no race with the design.
module axi4_lite_regs_tb;

    localparam [1:0]   OKAY     = 2'b00;
    localparam [1:0]   SLVERR   = 2'b10;
    localparam integer MAX_WAIT = 32;

    reg         aclk;
    reg         aresetn;
    reg  [3:0]  awaddr;
    reg         awvalid;
    wire        awready;
    reg  [31:0] wdata;
    reg  [3:0]  wstrb;
    reg         wvalid;
    wire        wready;
    wire [1:0]  bresp;
    wire        bvalid;
    reg         bready;
    reg  [3:0]  araddr;
    reg         arvalid;
    wire        arready;
    wire [31:0] rdata;
    wire [1:0]  rresp;
    wire        rvalid;
    reg         rready;

    integer        passed;
    integer        failed;
    integer        k;
    reg [8*64-1:0] nonce;
    reg [31:0]     model [0:3];

    axi4_lite_regs #(
        .ADDR_WIDTH (4),
        .DATA_WIDTH (32)
    ) dut (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (awaddr),
        .s_axil_awvalid (awvalid),
        .s_axil_awready (awready),
        .s_axil_wdata   (wdata),
        .s_axil_wstrb   (wstrb),
        .s_axil_wvalid  (wvalid),
        .s_axil_wready  (wready),
        .s_axil_bresp   (bresp),
        .s_axil_bvalid  (bvalid),
        .s_axil_bready  (bready),
        .s_axil_araddr  (araddr),
        .s_axil_arvalid (arvalid),
        .s_axil_arready (arready),
        .s_axil_rdata   (rdata),
        .s_axil_rresp   (rresp),
        .s_axil_rvalid  (rvalid),
        .s_axil_rready  (rready)
    );

    initial aclk = 1'b0;
    always #5 aclk = ~aclk;

    // ------------------------------------------------------------------
    // Reference model helpers
    // ------------------------------------------------------------------
    function mapped;
        input [3:0] a;
        begin
            mapped = (a[1:0] == 2'b00);
        end
    endfunction

    function [31:0] merge;
        input [31:0] old_word;
        input [31:0] new_word;
        input [3:0]  strb;
        integer i;
        begin
            merge = old_word;
            for (i = 0; i < 4; i = i + 1) begin
                if (strb[i]) begin
                    merge[8*i +: 8] = new_word[8*i +: 8];
                end
            end
        end
    endfunction

    function [31:0] expected_read;
        input [3:0] a;
        begin
            expected_read = mapped(a) ? model[a[3:2]] : 32'h0000_0000;
        end
    endfunction

    // ------------------------------------------------------------------
    // Checks
    // ------------------------------------------------------------------
    task check;
        input            cond;
        input [8*80-1:0] what;
        begin
            if (cond === 1'b1) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("[%0t] FAIL: %0s", $time, what);
            end
        end
    endtask

    task check32;
        input [31:0]     got;
        input [31:0]     exp;
        input [8*80-1:0] what;
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("[%0t] FAIL: %0s: got 0x%08h, expected 0x%08h", $time, what, got, exp);
            end
        end
    endtask

    // ------------------------------------------------------------------
    // Reset: asserts aresetn for 3 cycles, checks responses stay low and
    // READY is high after reset, and clears the model.
    // ------------------------------------------------------------------
    task do_reset;
        integer n;
        begin
            @(negedge aclk);
            aresetn = 1'b0;
            awvalid = 1'b0;
            wvalid  = 1'b0;
            arvalid = 1'b0;
            bready  = 1'b0;
            rready  = 1'b0;
            for (n = 0; n < 3; n = n + 1) begin
                @(negedge aclk);
                #4;
                check(bvalid === 1'b0, "reset: BVALID low during reset");
                check(rvalid === 1'b0, "reset: RVALID low during reset");
            end
            @(negedge aclk);
            aresetn = 1'b1;
            #4;
            check(bvalid === 1'b0,  "reset: BVALID low after reset");
            check(rvalid === 1'b0,  "reset: RVALID low after reset");
            check(awready === 1'b1, "reset: AWREADY high after reset");
            check(wready === 1'b1,  "reset: WREADY high after reset");
            check(arready === 1'b1, "reset: ARREADY high after reset");
            for (n = 0; n < 4; n = n + 1) begin
                model[n] = 32'h0000_0000;
            end
        end
    endtask

    // ------------------------------------------------------------------
    // Write transaction.
    //   aw_delay / w_delay: cycles before AWVALID / WVALID rise.
    //   b_delay: 0 = BREADY high before BVALID; N = hold BREADY low for N
    //   cycles after BVALID is seen.
    // ------------------------------------------------------------------
    task axi_write;
        input [3:0]   addr;
        input [31:0]  data;
        input [3:0]   strb;
        input integer aw_delay;
        input integer w_delay;
        input integer b_delay;
        reg       aw_done;
        reg       w_done;
        reg       b_seen;
        reg       b_done;
        reg [1:0] exp_resp;
        reg [1:0] first_resp;
        integer   cyc;
        integer   lat;
        integer   hold;
        begin
            exp_resp   = mapped(addr) ? OKAY : SLVERR;
            aw_done    = 1'b0;
            w_done     = 1'b0;
            b_seen     = 1'b0;
            b_done     = 1'b0;
            first_resp = OKAY;
            cyc        = 0;
            lat        = 0;
            hold       = 0;

            while (!(aw_done && w_done) && (cyc < MAX_WAIT)) begin
                @(negedge aclk);
                awvalid = !aw_done && (cyc >= aw_delay);
                awaddr  = awvalid ? addr : 4'h0;
                wvalid  = !w_done && (cyc >= w_delay);
                wdata   = wvalid ? data : 32'h0000_0000;
                wstrb   = wvalid ? strb : 4'h0;
                bready  = 1'b0;
                #4;
                check(bvalid === 1'b0, "write: no B response before AW and W are both accepted");
                if (awvalid && (cyc == aw_delay)) begin
                    check(awready === 1'b1, "write: AWREADY high on an idle write channel");
                end
                if (wvalid && (cyc == w_delay)) begin
                    check(wready === 1'b1, "write: WREADY high on an idle write channel");
                end
                if (awvalid && (awready === 1'b1)) begin
                    aw_done = 1'b1;
                end
                if (wvalid && (wready === 1'b1)) begin
                    w_done = 1'b1;
                end
                cyc = cyc + 1;
            end

            if (!(aw_done && w_done)) begin
                failed = failed + 1;
                $error("[%0t] FAIL: write to 0x%h not accepted within %0d cycles", $time, addr, MAX_WAIT);
            end else begin
                if (mapped(addr)) begin
                    model[addr[3:2]] = merge(model[addr[3:2]], data, strb);
                end
                while (!b_done && ((lat + hold) < MAX_WAIT)) begin
                    @(negedge aclk);
                    awvalid = 1'b0;
                    wvalid  = 1'b0;
                    bready  = (b_delay == 0) || (b_seen && (hold >= b_delay));
                    #4;
                    if (!b_seen) begin
                        lat = lat + 1;
                        if (bvalid === 1'b1) begin
                            b_seen     = 1'b1;
                            first_resp = bresp;
                            check(lat <= 2, "write: B within the 2-cycle latency bound");
                            check(bresp === exp_resp, "write: BRESP follows the address policy");
                        end
                    end else begin
                        check(bvalid === 1'b1, "write: BVALID holds until taken");
                        check(bresp === first_resp, "write: BRESP stable while waiting");
                    end
                    if (bvalid === 1'b1) begin
                        check((awready === 1'b0) && (wready === 1'b0),
                              "write: no new AW or W accepted while B is pending");
                    end
                    if (b_seen) begin
                        hold = hold + 1;
                    end
                    if ((bvalid === 1'b1) && bready) begin
                        b_done = 1'b1;
                    end
                end
                if (!b_done) begin
                    failed = failed + 1;
                    $error("[%0t] FAIL: write to 0x%h: B response not completed", $time, addr);
                end
            end
        end
    endtask

    // ------------------------------------------------------------------
    // Read transaction, checked against the model.
    //   ar_delay: cycles before ARVALID rises.
    //   r_delay: 0 = RREADY high before RVALID; N = hold RREADY low for N
    //   cycles after RVALID is seen.
    // ------------------------------------------------------------------
    task axi_read;
        input [3:0]   addr;
        input integer ar_delay;
        input integer r_delay;
        reg        ar_done;
        reg        r_seen;
        reg        r_done;
        reg [1:0]  exp_resp;
        reg [1:0]  first_resp;
        reg [31:0] exp_data;
        reg [31:0] first_data;
        integer    cyc;
        integer    lat;
        integer    hold;
        begin
            exp_resp   = mapped(addr) ? OKAY : SLVERR;
            exp_data   = expected_read(addr);
            ar_done    = 1'b0;
            r_seen     = 1'b0;
            r_done     = 1'b0;
            first_resp = OKAY;
            first_data = 32'h0000_0000;
            cyc        = 0;
            lat        = 0;
            hold       = 0;

            while (!ar_done && (cyc < MAX_WAIT)) begin
                @(negedge aclk);
                arvalid = (cyc >= ar_delay);
                araddr  = arvalid ? addr : 4'h0;
                rready  = 1'b0;
                #4;
                check(rvalid === 1'b0, "read: no R response before AR is accepted");
                if (arvalid && (cyc == ar_delay)) begin
                    check(arready === 1'b1, "read: ARREADY high on an idle read channel");
                end
                if (arvalid && (arready === 1'b1)) begin
                    ar_done = 1'b1;
                end
                cyc = cyc + 1;
            end

            if (!ar_done) begin
                failed = failed + 1;
                $error("[%0t] FAIL: read of 0x%h not accepted within %0d cycles", $time, addr, MAX_WAIT);
            end else begin
                while (!r_done && ((lat + hold) < MAX_WAIT)) begin
                    @(negedge aclk);
                    arvalid = 1'b0;
                    rready  = (r_delay == 0) || (r_seen && (hold >= r_delay));
                    #4;
                    if (!r_seen) begin
                        lat = lat + 1;
                        if (rvalid === 1'b1) begin
                            r_seen     = 1'b1;
                            first_resp = rresp;
                            first_data = rdata;
                            check(lat <= 2, "read: R within the 2-cycle latency bound");
                            check(rresp === exp_resp, "read: RRESP follows the address policy");
                            check32(rdata, exp_data, "read: RDATA matches the register model");
                        end
                    end else begin
                        check(rvalid === 1'b1, "read: RVALID holds until taken");
                        check(rresp === first_resp, "read: RRESP stable while waiting");
                        check32(rdata, first_data, "read: RDATA stable while waiting");
                    end
                    if (rvalid === 1'b1) begin
                        check(arready === 1'b0, "read: no new AR accepted while R is pending");
                    end
                    if (r_seen) begin
                        hold = hold + 1;
                    end
                    if ((rvalid === 1'b1) && rready) begin
                        r_done = 1'b1;
                    end
                end
                if (!r_done) begin
                    failed = failed + 1;
                    $error("[%0t] FAIL: read of 0x%h: R response not completed", $time, addr);
                end
            end
        end
    endtask

    // ------------------------------------------------------------------
    // Verdict
    // ------------------------------------------------------------------
    task finish_run;
        begin
            nonce = {64{8'h00}};
            if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) begin
                nonce = {64{8'h00}};
            end
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
            $finish;
        end
    endtask

    // ------------------------------------------------------------------
    // Test sequence
    // ------------------------------------------------------------------
    initial begin
        passed  = 0;
        failed  = 0;
        nonce   = {64{8'h00}};
        aresetn = 1'b0;
        awaddr  = 4'h0;
        awvalid = 1'b0;
        wdata   = 32'h0000_0000;
        wstrb   = 4'h0;
        wvalid  = 1'b0;
        bready  = 1'b0;
        araddr  = 4'h0;
        arvalid = 1'b0;
        rready  = 1'b0;
        for (k = 0; k < 4; k = k + 1) begin
            model[k] = 32'h0000_0000;
        end

        // 1. Reset values [AXIL-RESET]
        do_reset;
        axi_read(4'h0, 0, 0);
        axi_read(4'h4, 0, 0);
        axi_read(4'h8, 0, 0);
        axi_read(4'hC, 0, 0);

        // 2. Write then read every register (AW and W together)
        axi_write(4'h0, 32'hA5A5_0000, 4'hF, 0, 0, 0);
        axi_read(4'h0, 0, 0);
        axi_write(4'h4, 32'h5A5A_1111, 4'hF, 0, 0, 0);
        axi_read(4'h4, 0, 0);
        axi_write(4'h8, 32'hDEAD_BEEF, 4'hF, 0, 0, 0);
        axi_read(4'h8, 0, 0);
        axi_write(4'hC, 32'h0123_4567, 4'hF, 0, 0, 0);
        axi_read(4'hC, 0, 0);
        // No aliasing between registers.
        axi_read(4'h0, 0, 0);
        axi_read(4'h4, 0, 0);
        axi_read(4'h8, 0, 0);
        axi_read(4'hC, 0, 0);

        // 3. Byte enables [AXIL-WSTRB]
        axi_write(4'h8, 32'hFFFF_FFFF, 4'hF, 0, 0, 0);
        axi_write(4'h8, 32'h1122_3344, 4'b0101, 0, 0, 0);
        axi_read(4'h8, 0, 0);
        axi_write(4'h8, 32'hAABB_CCDD, 4'b1000, 0, 0, 0);
        axi_read(4'h8, 0, 0);
        axi_write(4'h8, 32'h0000_0000, 4'b0000, 0, 0, 0);   // no change, OKAY
        axi_read(4'h8, 0, 0);
        axi_write(4'hC, 32'hFFFF_FFFF, 4'hF, 0, 0, 0);
        for (k = 0; k < 4; k = k + 1) begin
            axi_write(4'hC, 32'h0000_0000, (4'b0001 << k), 0, 0, 0);
            axi_read(4'hC, 0, 0);
        end

        // 4. Write ordering [AXIL-ORDER]
        axi_write(4'h0, 32'hC0DE_0001, 4'hF, 0, 3, 0);   // AW 3 cycles before W
        axi_read(4'h0, 0, 0);
        axi_write(4'h4, 32'hC0DE_0002, 4'hF, 4, 0, 0);   // W 4 cycles before AW
        axi_read(4'h4, 0, 0);
        axi_write(4'h8, 32'hC0DE_0003, 4'hF, 1, 0, 0);   // W 1 cycle before AW
        axi_read(4'h8, 0, 0);
        axi_write(4'hC, 32'hC0DE_0004, 4'hF, 0, 1, 0);   // AW 1 cycle before W
        axi_read(4'hC, 0, 0);
        axi_write(4'h0, 32'hC0DE_0005, 4'hF, 2, 2, 0);   // together, after a gap
        axi_read(4'h0, 0, 0);

        // 5. B and R backpressure
        axi_write(4'h0, 32'hBAC4_0001, 4'hF, 0, 0, 5);
        axi_read(4'h0, 0, 5);
        axi_write(4'h4, 32'hBAC4_0002, 4'hF, 1, 3, 1);
        axi_read(4'h4, 2, 1);
        axi_write(4'h5, 32'hBAC4_0003, 4'hF, 2, 0, 3);   // SLVERR under backpressure
        axi_read(4'h6, 1, 4);                            // SLVERR under backpressure
        axi_read(4'h4, 0, 0);

        // 6. Back-to-back transactions [AXIL-B2B]
        for (k = 0; k < 8; k = k + 1) begin
            axi_write({k[1:0], 2'b00}, 32'hB2B0_0000 + k, 4'hF, 0, 0, 0);
        end
        for (k = 0; k < 8; k = k + 1) begin
            axi_read({k[1:0], 2'b00}, 0, 0);
        end

        // 7. SLVERR policy for unmapped addresses [AXIL-SLVERR]
        axi_write(4'h4, 32'h1111_2222, 4'hF, 0, 0, 0);
        axi_write(4'h5, 32'hDEAD_BEEF, 4'hF, 0, 0, 0);   // must not touch REG1
        axi_read(4'h4, 0, 0);
        axi_write(4'hE, 32'hDEAD_BEEF, 4'hF, 0, 0, 0);   // must not touch REG3
        axi_read(4'hC, 0, 0);
        axi_write(4'h1, 32'hFFFF_FFFF, 4'h0, 0, 0, 0);   // unmapped, zero strobe
        axi_write(4'h3, 32'hFFFF_FFFF, 4'hF, 3, 0, 2);   // unmapped, W first
        for (k = 0; k < 16; k = k + 1) begin
            axi_read(k[3:0], 0, 0);                      // full decode sweep
        end

        // 8. Read and write in flight at the same time
        fork
            axi_write(4'h8, 32'h600D_CAFE, 4'hF, 1, 2, 2);
            axi_read(4'hC, 0, 3);
        join
        axi_read(4'h8, 0, 0);
        fork
            axi_write(4'h0, 32'h0F0F_F0F0, 4'hF, 0, 0, 0);
            axi_read(4'h4, 0, 0);
        join
        axi_read(4'h0, 0, 0);

        // 9. Reset with work in flight [AXIL-RESET]
        // 9a. AW accepted alone, then reset: the half write is dropped.
        @(negedge aclk);
        awaddr  = 4'h4;
        awvalid = 1'b1;
        wvalid  = 1'b0;
        bready  = 1'b0;
        #4;
        check(awready === 1'b1, "half write: AW accepted alone");
        @(negedge aclk);
        awvalid = 1'b0;
        awaddr  = 4'h0;
        #4;
        check(awready === 1'b0, "half write: AW held while waiting for W");
        check(wready === 1'b1,  "half write: W still accepted while AW held");
        check(bvalid === 1'b0,  "half write: no response without W");
        do_reset;
        axi_write(4'h8, 32'hA5A5_0008, 4'hF, 3, 0, 0);   // W first after reset
        axi_read(4'h4, 0, 0);
        axi_read(4'h8, 0, 0);

        // 9b. W accepted alone, then reset.
        @(negedge aclk);
        wdata  = 32'hBADB_AD00;
        wstrb  = 4'hF;
        wvalid = 1'b1;
        awvalid = 1'b0;
        bready = 1'b0;
        #4;
        check(wready === 1'b1, "half write: W accepted alone");
        @(negedge aclk);
        wvalid = 1'b0;
        wdata  = 32'h0000_0000;
        wstrb  = 4'h0;
        #4;
        check(wready === 1'b0,  "half write: W held while waiting for AW");
        check(awready === 1'b1, "half write: AW still accepted while W held");
        check(bvalid === 1'b0,  "half write: no response without AW");
        do_reset;
        axi_write(4'hC, 32'hA5A5_000C, 4'hF, 0, 3, 0);   // AW first after reset
        axi_read(4'hC, 0, 0);
        axi_read(4'h0, 0, 0);

        // 9c. Reset while B is pending.
        @(negedge aclk);
        awaddr  = 4'h0;
        awvalid = 1'b1;
        wdata   = 32'h7777_7777;
        wstrb   = 4'hF;
        wvalid  = 1'b1;
        bready  = 1'b0;
        #4;
        check((awready === 1'b1) && (wready === 1'b1), "reset test: write accepted");
        @(negedge aclk);
        awvalid = 1'b0;
        wvalid  = 1'b0;
        #4;
        check(bvalid === 1'b1, "reset test: B pending before reset");
        do_reset;

        // 9d. Reset while R is pending.
        @(negedge aclk);
        araddr  = 4'h8;
        arvalid = 1'b1;
        rready  = 1'b0;
        #4;
        check(arready === 1'b1, "reset test: read accepted");
        @(negedge aclk);
        arvalid = 1'b0;
        #4;
        check(rvalid === 1'b1, "reset test: R pending before reset");
        do_reset;
        axi_read(4'h0, 0, 0);
        axi_read(4'h4, 0, 0);
        axi_read(4'h8, 0, 0);
        axi_read(4'hC, 0, 0);

        finish_run;
    end

    // Watchdog: a hung run still ends with a failing verdict.
    initial begin
        #1000000;
        failed = failed + 1;
        $error("[%0t] FAIL: watchdog timeout", $time);
        finish_run;
    end

endmodule

